"""Held-out GENERATED (control plane, seeded from frozen manifest, host-only)."""
from packaging.specifiers import InvalidSpecifier, SpecifierSet
from packaging.version import InvalidVersion, Version


def _norm(s):
    try:
        return str(Version(s))
    except InvalidVersion:
        return None


def _ge_contains(a, b):
    try:
        return SpecifierSet(">=" + a).contains(b)
    except InvalidSpecifier:
        return None


def test_generated_pins():
    assert _norm("1.0") == "1.0"
    assert _norm("2.0") == "2.0"
    assert _ge_contains("1.0", "2.0") == True
    assert _norm("abc") == None
    assert _norm("1.5") == "1.5"
    assert _ge_contains("abc", "1.5") == None
